<template>
<div class="sd-page"><div class="sd-page-inner">
<header class="sd-page-head"><div><p class="sd-eyebrow">Customer relationship</p><h1 class="sd-title">Customer 360°</h1><p class="sd-subtitle">A complete customer view: contact details, consent, conversations, notes and satisfaction.</p></div><div class="flex flex-wrap gap-2"><button class="sd-btn sd-btn-quiet" @click="exportCustomer">Export profile</button><button class="sd-btn sd-btn-primary" @click="addCustomer">＋ Add customer</button></div></header>
<div class="grid gap-4 xl:grid-cols-[340px_minmax(0,1fr)]">
<aside class="sd-card overflow-hidden"><div class="border-b p-4" style="border-color:var(--sd-border)"><div class="relative"><input v-model="search" class="sd-input pl-9" placeholder="Search customers…"><span class="absolute left-3 top-3 sd-muted">⌕</span></div><div class="mt-3 flex gap-1.5"><button v-for="f in ['All','VIP','Lead','Active']" :key="f" @click="filter=f" class="rounded-full px-3 py-1.5 text-[10px] font-semibold" :style="filter===f?'background:var(--sd-primary-soft);color:var(--sd-primary)':'background:var(--sd-surface-soft);color:var(--sd-muted)'">{{f}}</button></div></div>
<div class="max-h-[720px] overflow-y-auto p-2"><button v-for="c in filtered" :key="c.id" @click="selectedId=c.id" class="mb-1 flex w-full items-center gap-3 rounded-xl p-3 text-left transition" :style="selectedId===c.id?'background:var(--sd-primary-soft)':'background:transparent'"><span class="grid h-10 w-10 shrink-0 place-items-center rounded-full text-xs font-bold" style="background:var(--sd-surface-soft);color:var(--sd-primary)">{{initials(c.name)}}</span><span class="min-w-0 flex-1"><span class="block truncate text-xs font-bold">{{c.name}}</span><span class="mt-1 block truncate text-[10px] sd-muted">{{c.phone}}</span></span><span v-if="c.segment==='VIP'" class="rounded-full bg-amber-50 px-2 py-1 text-[9px] font-bold text-amber-700">VIP</span></button><p v-if="!filtered.length" class="p-6 text-center text-xs sd-muted">No customer found.</p></div>
</aside>
<main v-if="selected" class="min-w-0 space-y-4">
<section class="sd-card p-5"><div class="flex flex-wrap items-start justify-between gap-4"><div class="flex items-center gap-4"><span class="grid h-16 w-16 place-items-center rounded-2xl text-lg font-bold" style="background:var(--sd-primary-soft);color:var(--sd-primary)">{{initials(selected.name)}}</span><div><div class="flex flex-wrap items-center gap-2"><h2 class="text-lg font-bold">{{selected.name}}</h2><span v-if="selected.segment==='VIP'" class="rounded-full bg-amber-50 px-2 py-1 text-[10px] font-bold text-amber-700">VIP customer</span><span class="rounded-full px-2 py-1 text-[10px] font-semibold" style="background:var(--sd-primary-soft);color:var(--sd-primary)">{{selected.status}}</span></div><p class="mt-1 text-xs sd-muted">{{selected.phone}} · {{selected.email}}</p><p class="mt-1 text-[10px] sd-muted">Customer since {{selected.since}}</p></div></div><button @click="editCustomer" class="sd-btn sd-btn-quiet">Edit profile</button></div>
<div class="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div class="rounded-xl p-3" style="background:var(--sd-surface-soft)"><p class="text-[10px] sd-muted">Conversations</p><b class="mt-1 block text-xl">{{selected.conversations}}</b></div><div class="rounded-xl p-3" style="background:var(--sd-surface-soft)"><p class="text-[10px] sd-muted">Last interaction</p><b class="mt-1 block text-sm">{{selected.last}}</b></div><div class="rounded-xl p-3" style="background:var(--sd-surface-soft)"><p class="text-[10px] sd-muted">Average rating</p><b class="mt-1 block text-sm text-amber-500">{{selected.rating}} ★</b></div><div class="rounded-xl p-3" style="background:var(--sd-surface-soft)"><p class="text-[10px] sd-muted">Assigned agent</p><b class="mt-1 block text-sm">{{selected.agent}}</b></div></div></section>
<div class="grid gap-4 lg:grid-cols-[1fr_1fr]">
<section class="sd-card p-5"><div class="flex items-center justify-between"><h3 class="text-sm font-bold">Customer information</h3><span class="text-[10px] sd-muted">Profile details</span></div><dl class="mt-4 grid grid-cols-2 gap-x-4 gap-y-4 text-xs"><div><dt class="sd-muted">Phone number</dt><dd class="mt-1 font-semibold">{{selected.phone}}</dd></div><div><dt class="sd-muted">Email</dt><dd class="mt-1 break-all font-semibold">{{selected.email}}</dd></div><div><dt class="sd-muted">Location</dt><dd class="mt-1 font-semibold">{{selected.location}}</dd></div><div><dt class="sd-muted">Preferred language</dt><dd class="mt-1 font-semibold">{{selected.language}}</dd></div><div><dt class="sd-muted">Customer segment</dt><dd class="mt-1 font-semibold">{{selected.segment}}</dd></div><div><dt class="sd-muted">Source</dt><dd class="mt-1 font-semibold">{{selected.source}}</dd></div></dl><div class="mt-5 border-t pt-4" style="border-color:var(--sd-border)"><div class="flex items-center justify-between"><h4 class="text-xs font-bold">WhatsApp consent</h4><span class="rounded-full px-2 py-1 text-[10px] font-bold" :class="selected.optIn?'bg-emerald-50 text-emerald-700':'bg-rose-50 text-rose-700'">{{selected.optIn?'Opted in':'Opted out'}}</span></div><p class="mt-1 text-[10px] sd-muted">Marketing messages must respect the customer's recorded consent.</p><button class="mt-3 text-xs font-semibold" style="color:var(--sd-primary)" @click="toggleConsent">{{selected.optIn?'Record opt-out':'Record opt-in'}}</button></div><div class="mt-4"><h4 class="text-xs font-bold">Tags</h4><div class="mt-2 flex flex-wrap gap-1.5"><span v-for="tag in selected.tags" :key="tag" class="rounded-full px-2.5 py-1 text-[10px] font-semibold" style="background:var(--sd-surface-soft)">{{tag}}</span><button @click="addTag" class="rounded-full border px-2.5 py-1 text-[10px] font-semibold sd-muted" style="border-color:var(--sd-border)">＋ Add tag</button></div></div></section>
<section class="sd-card p-5"><div class="flex items-center justify-between"><h3 class="text-sm font-bold">Internal notes</h3><button @click="addNote" class="text-xs font-semibold" style="color:var(--sd-primary)">＋ Add note</button></div><div class="mt-4 space-y-3"><article v-for="(n,i) in selected.notes" :key="i" class="rounded-xl p-3" style="background:var(--sd-surface-soft)"><p class="text-xs leading-5">{{n.text}}</p><p class="mt-2 text-[10px] sd-muted">{{n.author}} · {{n.date}}</p></article><p v-if="!selected.notes.length" class="text-xs sd-muted">No internal notes yet.</p></div></section>
</div>
<section class="sd-card p-5"><div class="flex flex-wrap items-center justify-between gap-2"><div><h3 class="text-sm font-bold">Customer activity timeline</h3><p class="mt-1 text-xs sd-muted">Recent conversations and customer events.</p></div><NuxtLink to="/dashboard/inbox" class="sd-btn sd-btn-quiet">Open inbox</NuxtLink></div><div class="mt-5 space-y-4"><div v-for="(event,i) in selected.timeline" :key="i" class="flex gap-3"><span class="mt-1 h-2.5 w-2.5 shrink-0 rounded-full" :style="{background:i===0?'var(--sd-primary)':'#9aa9a5'}"></span><div class="min-w-0 flex-1"><p class="text-xs font-semibold">{{event.title}}</p><p class="mt-1 text-xs sd-muted">{{event.detail}}</p><p class="mt-1 text-[10px] sd-muted">{{event.date}}</p></div></div></div></section>
</main><div v-else class="sd-card grid min-h-64 place-items-center p-8 text-center text-sm sd-muted">Select a customer to view their profile.</div>
</div>
<div v-if="modal" class="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4" @click.self="modal=false"><div class="sd-card w-full max-w-lg p-5"><div class="flex items-center justify-between"><h3 class="text-base font-bold">{{modalMode==='edit'?'Edit customer':'Add customer'}}</h3><button @click="modal=false" class="sd-muted">✕</button></div><div class="mt-4 grid gap-3 sm:grid-cols-2"><label v-for="field in ['name','phone','email','location','language','segment']" :key="field" class="text-xs font-semibold capitalize">{{field}}<input v-model="form[field]" class="sd-input mt-1.5" :placeholder="field"></label></div><div class="mt-5 flex justify-end gap-2"><button @click="modal=false" class="sd-btn sd-btn-quiet">Cancel</button><button @click="saveCustomer" class="sd-btn sd-btn-primary">Save customer</button></div></div></div>
<div v-if="notice" class="fixed bottom-5 right-5 z-50 rounded-xl bg-slate-900 px-4 py-3 text-xs font-semibold text-white shadow-xl">{{notice}}</div>
</div></div>
</template>
<script setup lang="ts">
import {computed,ref,reactive,onMounted,watch} from 'vue'
definePageMeta({layout:'dashboard'});useHead({title:'Customer 360° — SumashDesk'})
type Customer={id:number;name:string;phone:string;email:string;location:string;language:string;segment:string;status:string;since:string;conversations:number;last:string;rating:string;agent:string;source:string;optIn:boolean;tags:string[];notes:{text:string;author:string;date:string}[];timeline:{title:string;detail:string;date:string}[]}
const seed:Customer[]=[
{id:1,name:'Sumon Kundu',phone:'+8801714932410',email:'sumon@example.com',location:'Dhaka, Bangladesh',language:'Bengali',segment:'VIP',status:'Active',since:'12 Jan 2025',conversations:12,last:'Today, 11:42 AM',rating:'4.8',agent:'Nusrat Jahan',source:'WhatsApp',optIn:true,tags:['VIP','Repeat customer','Priority support'],notes:[{text:'Prefers a call-back after 5 PM. Keep updates concise.',author:'Nusrat Jahan',date:'Today · 10:20 AM'},{text:'Long-term customer; follow up on pending query.',author:'Sadikul Islam',date:'Nov 02, 2026'}],timeline:[{title:'Conversation resolved',detail:'Product information shared and customer confirmed resolution.',date:'Today · 11:42 AM'},{title:'Customer rated support 5 stars',detail:'“Very helpful and quick response.”',date:'Nov 02, 2026'},{title:'Contact added to VIP Customers',detail:'Segment updated by team admin.',date:'Oct 18, 2026'}]},
{id:2,name:'Shalvi Hasan',phone:'+8801812450821',email:'shalvi@example.com',location:'Chattogram, Bangladesh',language:'Bengali',segment:'Lead',status:'Active',since:'18 Mar 2026',conversations:3,last:'Today, 10:18 AM',rating:'4.0',agent:'Mahmud Hasan',source:'WhatsApp',optIn:true,tags:['Interested','Follow-up'],notes:[],timeline:[{title:'New conversation started',detail:'Asked for product details and availability.',date:'Today · 10:18 AM'},{title:'Follow-up reminder created',detail:'Agent scheduled a follow-up.',date:'Yesterday'}]},
{id:3,name:'Mahbub Rahman',phone:'+8801911220345',email:'mahbub@example.com',location:'Sylhet, Bangladesh',language:'English',segment:'Regular',status:'Active',since:'04 Aug 2026',conversations:1,last:'Yesterday',rating:'2.0',agent:'Rafi Ahmed',source:'WhatsApp',optIn:false,tags:['Support issue'],notes:[],timeline:[{title:'Support issue reported',detail:'Customer asked for assistance.',date:'Yesterday'}]}
]
const customers=ref<Customer[]>(seed),selectedId=ref(1),search=ref(''),filter=ref('All'),modal=ref(false),modalMode=ref('add'),notice=ref('')
const selected=computed(()=>customers.value.find(c=>c.id===selectedId.value))
const filtered=computed(()=>customers.value.filter(c=>(filter.value==='All'||c.segment===filter.value||c.status===filter.value)&& (c.name+' '+c.phone+' '+c.email).toLowerCase().includes(search.value.toLowerCase())))
const form=reactive<Record<string,string>>({name:'',phone:'',email:'',location:'',language:'Bengali',segment:'Regular'})
onMounted(()=>{try{const s=localStorage.getItem('sumashdesk-customer-360');if(s)customers.value=JSON.parse(s)}catch{}})
watch(customers,v=>localStorage.setItem('sumashdesk-customer-360',JSON.stringify(v)),{deep:true})
function initials(name:string){return name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function notify(m:string){notice.value=m;setTimeout(()=>notice.value='',2300)}
function addCustomer(){modalMode.value='add';Object.assign(form,{name:'',phone:'',email:'',location:'',language:'Bengali',segment:'Regular'});modal.value=true}
function editCustomer(){if(!selected.value)return;modalMode.value='edit';Object.assign(form,{name:selected.value.name,phone:selected.value.phone,email:selected.value.email,location:selected.value.location,language:selected.value.language,segment:selected.value.segment});modal.value=true}
function saveCustomer(){if(!form.name.trim()||!form.phone.trim()){notify('Name and phone are required');return}if(modalMode.value==='edit'&&selected.value){Object.assign(selected.value,form)}else{const id=Date.now();customers.value.unshift({id,name:form.name,phone:form.phone,email:form.email,location:form.location,language:form.language,segment:form.segment,status:'Active',since:'Today',conversations:0,last:'No interaction',rating:'—',agent:'Unassigned',source:'Manual entry',optIn:false,tags:[],notes:[],timeline:[{title:'Customer profile created',detail:'Added manually to SumashDesk.',date:'Today'}]});selectedId.value=id}modal.value=false;notify('Customer profile saved')}
function toggleConsent(){if(selected.value){selected.value.optIn=!selected.value.optIn;selected.value.timeline.unshift({title:selected.value.optIn?'Marketing opt-in recorded':'Marketing opt-out recorded',detail:'Consent updated manually by workspace team.',date:'Just now'});notify('Consent record updated')}}
function addTag(){const t=prompt('Enter a customer tag');if(t?.trim()&&selected.value){selected.value.tags.push(t.trim());notify('Tag added')}}
function addNote(){const t=prompt('Write an internal customer note');if(t?.trim()&&selected.value){selected.value.notes.unshift({text:t.trim(),author:'Sadikul Islam',date:'Just now'});selected.value.timeline.unshift({title:'Internal note added',detail:t.trim(),date:'Just now'});notify('Note saved')}}
function exportCustomer(){if(!selected.value)return;const blob=new Blob([JSON.stringify(selected.value,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`customer-${selected.value.id}.json`;a.click();URL.revokeObjectURL(a.href);notify('Customer profile exported')}
</script>